    /**
     * Walk toward a leaf, recording each level of children on the given iterator.
     */
    private void fillStackToLeaf(PostOrderIterator iterator) {
        Node current = this;
        while (true) {
            List<Node> children;
            if (current instanceof CompilationUnit) {
                CompilationUnit compilationUnit = (CompilationUnit) current;
                children = new ArrayList<>();
                compilationUnit.getPackageDeclaration().ifPresent(children::add);
                children.addAll(compilationUnit.getImports());
                children.addAll(compilationUnit.getTypes());
                compilationUnit.getModule().ifPresent(children::add);
            } else {
                children = new ArrayList<>();
                for (Node child : current.getChildNodes()) {
                    if (child.getParentNode().orElse(null) == current) {
                        children.add(child);
                    }
                }
            }
            if (children.isEmpty()) {
                break;
            }
            iterator.nodesStack.push(children);
            iterator.cursorStack.push(0);
            current = children.get(0);
        }
    }

    /**
     * Performs a post-order (or leaves-first) node traversal starting with a given node.
     *
     * @see <a href="https://en.wikipedia.org/wiki/Post-order">Post-order traversal</a>
     */
    public static class PostOrderIterator implements Iterator<Node> {

        private final Stack<List<Node>> nodesStack = new Stack<>();

        private final Stack<Integer> cursorStack = new Stack<>();

        private final Node root;

        private boolean hasNext = true;

        public PostOrderIterator(Node root) {
            this.root = root;
            root.fillStackToLeaf(this);
        }

        @Override
        public boolean hasNext() {
            return hasNext;
        }

        @Override
        public Node next() {
            final List<Node> nodes = nodesStack.peek();
            final int cursor = cursorStack.peek();
            final boolean levelHasNext = cursor < nodes.size();
            if (levelHasNext) {
                Node node = nodes.get(cursor);
                node.fillStackToLeaf(this);
                return nextFromLevel();
            }
            nodesStack.pop();
            cursorStack.pop();
            hasNext = !nodesStack.empty();
            if (hasNext) {
                return nextFromLevel();
            }
            return root;
        }

        private Node nextFromLevel() {
            final List<Node> nodes = nodesStack.peek();
            final int cursor = cursorStack.pop();
            cursorStack.push(cursor + 1);
            return nodes.get(cursor);
        }
    }

    /*
